  // comparison must drop them from the live side. Every glyph/verb pair
  // of the four-state vocabulary is pinned: a renderer vocabulary change
  // must consciously re-derive this matcher (a silent miss shifts the
  // AC1 alignment window by one row and fails the PTY run below with a
  // confusing off-by-one diff).
  test('gh-1415: subagent board rows are chrome, never transcript grammar', () {
    for (final row in [
      '⠿ run pty446             0s    – reply with the single word ok',
      '⏸ wait pty446             0s    – reply with the single word ok',
      '✓ done pty446             0s    – reply with the single word ok',
      '✗ fail pty446             0s    – reply with the single word ok',
    ]) {
      expect(transcriptOf(['>_Fa mid-turn row', row]), [
        '>_Fa mid-turn row',
      ], reason: 'subagent board row leaked into the transcript: $row');
    }
    // The settled band tool cards (✔/✘) are the ONLY tool-row grammar —
    // the new rule must not eat them (the #916 drift detection stays).
    expect(transcriptOf(['✔ bash: echo pinned-render-1']), [
      'bash: echo pinned-render-1',
    ]);
  });

  late Directory home;
  late Directory project;
  late File turnsFile;

  setUp(() async {
    // Unique SHORT dirs (the #936/#938 class — fixed /tmp paths race
    // concurrent suite copies). Long macOS temp paths wrap mid-path and
    // desync the two frames' wrap continuations (#446); /tmp keeps every
    // row on one physical line.
    home = Directory('/tmp').createTempSync('fa446h');
    project = Directory('/tmp').createTempSync('fa446p');
    // Pin the classic chrome: this suite asserts the classic transcript
    // grammar; the band redesign (#805-#807) has its own surface. The
    // harness configures providers via FA_PROVIDER_CONFIG env only, so the
    // pin rides its own tiny config.yaml.
    File('${home.path}/.fah/config.yaml')
      ..createSync(recursive: true)
      ..writeAsStringSync('tui:\n  classic: true\n');
    turnsFile = File('${home.path}/fa_446_turns.json')
      ..writeAsStringSync(jsonEncode(_turns));
  });

  tearDown(() async {
    await home.delete(recursive: true);
    await project.delete(recursive: true);
  });

  Map<String, String> env() => {
    'HOME': home.path,
    'FA_TEST_STREAM_SCRIPT': turnsFile.path,
    'FA_PROVIDER_TYPE': 'openai',
    'FA_PROVIDER_CONFIG': jsonEncode({
      'baseUrl': 'http://127.0.0.1:9', // never dialed — the script streams
      'model': 'pty-scripted',
    }),
  };

  test('AC1: resume renders 1:1 with live (normalized diff empty)', () async {
    // --- live run: fresh session, one scripted turn, graceful exit.
    final live = await FaCliHarness.spawn(
      workingDirectory: project.path,
      extraEnv: env(),
      args: ['--session', 'pty446'],
    );
    try {
      await live.waitForBoot();
      live.sendText(_prompt);
      live.sendEnter();
      await live.waitForText(
        _replyMarker,
        timeout: const Duration(seconds: 60),
      );
      await live.waitForText(
        'Background shell job',
        timeout: const Duration(seconds: 30),
      );
      await live.waitForOutput(
        settleMs: 700,
        timeout: const Duration(seconds: 20),
      );
      final liveScreen = live.viewportLines;
      await live.runSlashCommand('/exit');
      await live.pty.exitCode.timeout(
        const Duration(seconds: 15),
        onTimeout: () => -1,
      );
      // --- the resumed run: same session, fresh process.
      final resumed = await FaCliHarness.spawn(
        workingDirectory: project.path,
        extraEnv: env(),
        args: ['--session', 'pty446'],
      );
      try {
        // The boot banners scroll out of the small viewport once the
        // replayed tail renders; wait for the tail instead.
        await resumed.waitForText(
          _replyMarker,
          timeout: const Duration(seconds: 60),
        );
        await resumed.waitForOutput(
          settleMs: 700,
          timeout: const Duration(seconds: 20),
        );
        final resumeScreen = resumed.viewportLines;
        final resumeText = resumed.screenText;

        // Contract: zero fallback markers on the resumed screen.
        expect(resumeText, isNot(contains('[bash]')));
        expect(resumeText, isNot(contains('[task]')));
