final _runningCard = RegExp(r'^[⟳⏳] \S+: ');

/// A live SETTLED band tool card (`✔ bash: sleep 2 … 0s`, `✘ … [exit 1]`).
final _settledCard = RegExp(r'^[✔✘] (\S+): (.+)$');

